//! Synthetic "sung" and "hummed" melodies with known notes (generated by code, never
//! binary fixtures).
#![allow(dead_code)]

use super::eval::EvalNote;
use std::f64::consts::PI;

/// A note of a fixture melody.
#[derive(Clone, Copy, Debug)]
pub struct FixNote {
    pub midi: f64,
    /// Slot start (the reference onset; the centre of a glide for portamento notes).
    pub start: f64,
    /// Sounding duration.
    pub dur: f64,
    /// Level relative to the loudest note (dB).
    pub gain_db: f64,
    /// Portamento from the previous note (seconds, centred on `start`); 0 = none. Only
    /// meaningful when the previous note ends exactly at `start` (legato).
    pub glide: f64,
    /// Detuning of the sung pitch (cents).
    pub detune_cents: f64,
}

/// Voice character.
#[derive(Clone, Debug)]
pub struct Voice {
    /// Formants (Hz, bandwidth Hz).
    pub formants: Vec<(f64, f64)>,
    /// Harmonic k has amplitude 1/k^rolloff.
    pub rolloff: f64,
    pub vib_hz: f64,
    pub vib_cents: f64,
    pub vib_delay: f64,
    /// Peak of a slow random pitch drift per note (cents).
    pub drift_cents: f64,
    pub attack: f64,
    pub release: f64,
    /// Breath noise level relative to the harmonic excitation RMS (dB); None = none.
    pub breath_db: Option<f64>,
    /// Room noise level relative to the voice RMS (dB); None = none.
    pub room_db: Option<f64>,
    pub seed: u64,
}

impl Voice {
    /// A clean sung vowel /a/.
    pub fn sung_a() -> Voice {
        Voice {
            formants: vec![(730.0, 90.0), (1090.0, 110.0), (2440.0, 160.0)],
            rolloff: 1.0,
            vib_hz: 5.5,
            vib_cents: 35.0,
            vib_delay: 0.18,
            drift_cents: 0.0,
            attack: 0.025,
            release: 0.03,
            breath_db: None,
            room_db: None,
            seed: 1,
        }
    }
    /// A sung /u/ (darker, low first formant).
    pub fn sung_u() -> Voice {
        Voice { formants: vec![(300.0, 60.0), (870.0, 90.0), (2240.0, 150.0)], seed: 2, ..Voice::sung_a() }
    }
    /// Breathy closed-mouth humming: steep harmonic roll-off, nasal formants, drift, soft
    /// onsets, breath noise, and room noise.
    pub fn hummed() -> Voice {
        Voice {
            formants: vec![(250.0, 100.0), (1000.0, 200.0), (2200.0, 300.0)],
            rolloff: 1.8,
            vib_hz: 4.5,
            vib_cents: 15.0,
            vib_delay: 0.25,
            drift_cents: 20.0,
            attack: 0.07,
            release: 0.06,
            breath_db: Some(-18.0),
            room_db: Some(-30.0),
            seed: 3,
        }
    }
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> f64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 >> 11) as f64 / (1u64 << 53) as f64
    }
    fn gauss(&mut self) -> f64 {
        let u1 = self.next().max(1e-12);
        let u2 = self.next();
        (-2.0 * u1.ln()).sqrt() * (2.0 * PI * u2).cos()
    }
}

/// Render a melody. Returns mono samples peaking at about 0.5.
pub fn sing(sr: u32, notes: &[FixNote], v: &Voice) -> Vec<f32> {
    let srf = sr as f64;
    let end = notes.iter().map(|n| n.start + n.dur).fold(0.0, f64::max) + 0.4;
    let len = (end * srf) as usize;
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15 ^ v.seed.wrapping_mul(0x2545_F491_4F6C_DD1D));
    // per-note drift endpoints
    let drift: Vec<(f64, f64)> = notes
        .iter()
        .map(|_| ((rng.next() * 2.0 - 1.0) * v.drift_cents, (rng.next() * 2.0 - 1.0) * v.drift_cents))
        .collect();
    let mut f0 = vec![0.0f64; len];
    let mut amp = vec![0.0f64; len];
    for (i, n) in notes.iter().enumerate() {
        let s = (n.start * srf) as usize;
        let e = (((n.start + n.dur) * srf) as usize).min(len);
        let legato_in = i > 0 && (notes[i - 1].start + notes[i - 1].dur - n.start).abs() < 1e-6;
        let legato_out = i + 1 < notes.len() && (n.start + n.dur - notes[i + 1].start).abs() < 1e-6;
        let g = 10f64.powf(n.gain_db / 20.0);
        for k in s..e {
            let t = k as f64 / srf - n.start;
            let frac = t / n.dur;
            let cents = n.detune_cents
                + drift[i].0 + (drift[i].1 - drift[i].0) * frac
                + if t > v.vib_delay {
                    let ramp = ((t - v.vib_delay) / 0.15).min(1.0);
                    ramp * v.vib_cents * (2.0 * PI * v.vib_hz * t).sin()
                } else {
                    0.0
                };
            let mut m = n.midi + cents / 100.0;
            // portamento centred on the boundary
            if legato_in && n.glide > 0.0 && t < n.glide / 2.0 {
                let p = &notes[i - 1];
                let a = 0.5 + t / n.glide;
                let prev = p.midi + p.detune_cents / 100.0;
                m = prev + (m - prev) * smooth(a);
            }
            if legato_out && notes[i + 1].glide > 0.0 && n.dur - t < notes[i + 1].glide / 2.0 {
                let q = &notes[i + 1];
                let a = 0.5 - (n.dur - t) / q.glide;
                let next = q.midi + q.detune_cents / 100.0;
                m += (next - m) * smooth(a);
            }
            f0[k] = 440.0 * 2f64.powf((m - 69.0) / 12.0);
            // envelope
            let att = if legato_in { 1.0 } else { smooth((t / v.attack).min(1.0)) };
            let rel = if legato_out { 1.0 } else { smooth(((n.dur - t) / v.release).min(1.0)) };
            let mut a = g * att * rel;
            if legato_in {
                // crossfade the level from the previous note over 30 ms
                let gp = 10f64.powf(notes[i - 1].gain_db / 20.0);
                if t < 0.015 {
                    a = gp + (g - gp) * (0.5 + t / 0.03);
                }
            }
            if legato_out {
                let gn = 10f64.powf(notes[i + 1].gain_db / 20.0);
                if n.dur - t < 0.015 {
                    a = g + (gn - g) * (0.5 - (n.dur - t) / 0.03);
                }
            }
            amp[k] = a;
        }
    }
    // excitation: band-limited harmonics with 1/k^rolloff amplitudes
    let mut phase = 0.0f64;
    let mut src = vec![0.0f64; len];
    let mut last_f = 200.0;
    for k in 0..len {
        let f = if f0[k] > 0.0 { f0[k] } else { last_f };
        last_f = f;
        phase += 2.0 * PI * f / srf;
        if phase > 2.0 * PI {
            phase -= 2.0 * PI;
        }
        if amp[k] <= 0.0 {
            continue;
        }
        let kmax = ((0.45 * srf / f).floor() as usize).max(1);
        let c2 = 2.0 * phase.cos();
        let (mut s1, mut s2) = (phase.sin(), 0.0f64);
        let mut acc = 0.0;
        for h in 1..=kmax {
            acc += s1 / (h as f64).powf(v.rolloff);
            let s0 = c2 * s1 - s2;
            s2 = s1;
            s1 = s0;
        }
        src[k] = acc * amp[k];
    }
    if let Some(bdb) = v.breath_db {
        let rms = (src.iter().map(|x| x * x).sum::<f64>() / len.max(1) as f64).sqrt();
        let peak_amp = amp.iter().cloned().fold(0.0, f64::max).max(1e-9);
        let lvl = rms * 10f64.powf(bdb / 20.0) / (peak_amp * 0.6);
        for k in 0..len {
            src[k] += rng.gauss() * lvl * amp[k];
        }
    }
    // formant resonators
    let mut y = src;
    for &(fc, bw) in &v.formants {
        let c = -(-2.0 * PI * bw / srf).exp();
        let b = 2.0 * (-PI * bw / srf).exp() * (2.0 * PI * fc / srf).cos();
        let a = 1.0 - b - c;
        let (mut y1, mut y2) = (0.0, 0.0);
        for x in y.iter_mut() {
            let o = a * *x + b * y1 + c * y2;
            y2 = y1;
            y1 = o;
            *x = o;
        }
    }
    let peak = y.iter().fold(0.0f64, |m, x| m.max(x.abs())).max(1e-9);
    y.iter_mut().for_each(|x| *x *= 0.5 / peak);
    if let Some(rdb) = v.room_db {
        let voiced: Vec<f64> = y.iter().zip(&amp).filter(|(_, a)| **a > 0.0).map(|(x, _)| *x).collect();
        let rms = (voiced.iter().map(|x| x * x).sum::<f64>() / voiced.len().max(1) as f64).sqrt();
        let lvl = rms * 10f64.powf(rdb / 20.0);
        // brownish room noise: one-pole low-passed white noise, normalised to `lvl` RMS
        let mut lp = 0.0;
        let mut n: Vec<f64> = (0..len)
            .map(|_| {
                lp = 0.97 * lp + 0.03 * rng.gauss();
                lp + 0.05 * rng.gauss()
            })
            .collect();
        let nr = (n.iter().map(|x| x * x).sum::<f64>() / len as f64).sqrt().max(1e-12);
        n.iter_mut().for_each(|x| *x *= lvl / nr);
        for (x, z) in y.iter_mut().zip(n) {
            *x += z;
        }
    }
    y.into_iter().map(|x| x as f32).collect()
}

fn smooth(a: f64) -> f64 {
    let a = a.clamp(0.0, 1.0);
    0.5 - 0.5 * (PI * a).cos()
}

/// Reference notes for evaluation.
pub fn reference(notes: &[FixNote]) -> Vec<EvalNote> {
    notes.iter().map(|n| EvalNote { onset_s: n.start, offset_s: n.start + n.dur, midi: n.midi }).collect()
}

/// Build a melody from (midi, beats, gap_beats, gain_db, glide_s) at `bpm`, starting at
/// `t0`. `gap_beats` of silence end each note's slot (0 = legato into the next note).
pub fn melody(bpm: f64, t0: f64, spec: &[(f64, f64, f64, f64, f64)]) -> Vec<FixNote> {
    let beat = 60.0 / bpm;
    let mut t = t0;
    spec.iter()
        .map(|&(m, beats, gap, gain, glide)| {
            let n = FixNote {
                midi: m,
                start: t,
                dur: (beats - gap) * beat,
                gain_db: gain,
                glide,
                detune_cents: 0.0,
            };
            t += beats * beat;
            n
        })
        .collect()
}

/// Ode-to-joy-like line in C major at 100 BPM: eighths and quarters, legato steps with
/// portamento, repeated notes separated by short gaps, loudness varying over 12 dB.
pub fn melody_a(transpose: f64) -> Vec<FixNote> {
    let m = |x: f64| x + transpose;
    melody(
        100.0,
        0.30,
        &[
            (m(64.0), 1.0, 0.15, 0.0, 0.0),
            (m(64.0), 1.0, 0.0, -2.0, 0.0),
            (m(65.0), 1.0, 0.0, -1.0, 0.08),
            (m(67.0), 1.0, 0.15, 0.0, 0.0),
            (m(67.0), 0.5, 0.0, -4.0, 0.0),
            (m(65.0), 0.5, 0.0, -6.0, 0.06),
            (m(64.0), 1.0, 0.0, -3.0, 0.1),
            (m(62.0), 1.0, 0.2, -8.0, 0.0),
            (m(60.0), 1.0, 0.15, -12.0, 0.0),
            (m(60.0), 0.5, 0.1, -9.0, 0.0),
            (m(62.0), 0.5, 0.0, -6.0, 0.0),
            (m(64.0), 1.0, 0.1, -2.0, 0.0),
            (m(64.0), 1.5, 0.0, 0.0, 0.0),
            (m(62.0), 0.5, 0.12, -5.0, 0.07),
            (m(62.0), 2.0, 0.5, -3.0, 0.0),
        ],
    )
}

