/// A seeded random diatonic melody: `n` notes, steps of up to a fifth within a major or
/// minor scale, staying within four scale steps of `centre`, durations of 1/2 to 2 beats at a tempo between 80 and 130
/// BPM, legato steps (30% with portamento) or re-articulated with gaps, levels over 12 dB.
/// Repeated pitches are always re-articulated. Returns the notes and the tempo.
pub fn random_melody(seed: u64, centre: i32, n: usize) -> (Vec<FixNote>, f64) {
    let mut r = Rng(0xA076_1D64_78BD_642F ^ seed.wrapping_mul(0xE703_7ED1_A0B4_28DB).wrapping_add(1));
    let bpm = (80.0 + 50.0 * r.next()).round();
    let minor = r.next() < 0.4;
    let steps: [i32; 7] = if minor { [0, 2, 3, 5, 7, 8, 10] } else { [0, 2, 4, 5, 7, 9, 11] };
    let scale: Vec<i32> = (-2..=2).flat_map(|o| steps.iter().map(move |s| centre + 12 * o + s)).collect();
    let home = scale.iter().position(|&m| m == centre).unwrap_or(14) as i32;
    let mut idx = home;
    let durs = [0.5, 0.5, 1.0, 1.0, 1.0, 1.5, 2.0];
    let mut spec = Vec::with_capacity(n);
    for _ in 0..n {
        let step = [-4, -3, -2, -1, -1, 0, 1, 1, 2, 3, 4][(r.next() * 11.0) as usize % 11];
        // stay within about an octave around the centre (a comfortable vocal range)
        idx = (idx + step).clamp(home - 4, home + 4);
        let m = scale[idx as usize];
        let beats = durs[(r.next() * durs.len() as f64) as usize % durs.len()];
        let gain = -12.0 * r.next();
        spec.push((m, beats, gain));
    }
    let mut notes_spec = Vec::with_capacity(n);
    for i in 0..n {
        let (m, beats, gain) = spec[i];
        let next_same = i + 1 < n && spec[i + 1].0 == m;
        let legato = !next_same && i + 1 < n && r.next() < 0.5;
        let gap = if legato { 0.0 } else { (0.1 + 0.15 * r.next()).min(beats * 0.4) };
        let glide = if i > 0 && notes_spec.last().map(|p: &(f64, f64, f64, f64, f64)| p.2 == 0.0).unwrap_or(false) && r.next() < 0.3 {
            0.05 + 0.07 * r.next()
        } else {
            0.0
        };
        notes_spec.push((m as f64, beats, gap, gain, glide));
    }
    (melody(bpm, 0.3, &notes_spec), bpm)
}
